def double(x):
    return x * 2

cases = [
    ('double of 3', double, 3, 6),
    ('double of 0', double, 0, 0),
    ('double of -4', double, -4, -8),
]

passed = 0
failed = 0
for name, fn, arg, expected in cases:
    if fn(arg) == expected:
        passed = passed + 1
    else:
        failed = failed + 1
        print('FAILED:', name)

print('passed: %d failed: %d' % (passed, failed))

hits = {'init': 0, 'body': 0, 'negative': 0, 'done': 0}
edges = {'d1-T': 0, 'd1-F': 0, 'd2-T': 0, 'd2-F': 0}

def classify_and_sum(n):
    hits['init'] += 1
    total = 0
    i = 1
    while i <= n:
        edges['d2-T'] += 1
        hits['body'] += 1
        total = total + i
        i = i + 1
    edges['d2-F'] += 1
    if n < 0:
        edges['d1-T'] += 1
        hits['negative'] += 1
    else:
        edges['d1-F'] += 1
    hits['done'] += 1
    return total

def covered(counter):
    n = 0
    for key in counter:
        if counter[key] > 0:
            n += 1
    return n

for n in [3, 0]:
    classify_and_sum(n)

print('statements: %d/4 | branches: %d/4' % (covered(hits), covered(edges)))

classify_and_sum(-5)

print('statements: %d/4 | branches: %d/4' % (covered(hits), covered(edges)))

seen = []

def normalize_grade(score):
    if score < 0 or score > 100:
        seen.append('invalid')
        return -1
    if score < 60:
        seen.append('fail')
        return 0
    if score < 80:
        seen.append('pass')
        return 1
    seen.append('high')
    return 2

cases = [
    ('zero', 0, 0),
    ('fail edge', 59, 0),
    ('pass edge', 79, 1),
    ('high edge', 80, 2),
]

passed = 0
for name, arg, expected in cases:
    if normalize_grade(arg) == expected:
        passed = passed + 1
    else:
        print('FAILED:', name, '-> got %s' % normalize_grade(arg))

print('tests: %d passed: %d' % (len(cases), passed))
